<?php
/** Proof — the activity server (surface: record_history, actor_timeline, who_touched, period_activity, config_change_log, changes_since, activity_search): the log in words and facts, scoped by the view; nothing secret in any payload. */
require __DIR__ . '/lib.php';
$W = p4world();
$BEA = 27; $CARL = 28; $VERA = 26; $OWNER = 1;
$A = fn (int $m, string $t, array $a = []) => tool($m, $t, $a, ACT);
$AD = fn (int $m, string $t, array $a = []) => tdata($m, $t, $a, ACT);
echo "1. record_history\n";
$capNum = (string) one('SELECT number FROM journal_entries WHERE id = :i', ['i' => $W['capital']]);
$h = $AD($BEA, 'record_history', ['record_type' => 'journal_entry', 'record_id' => $W['capital']]);
$acts = array_column($h['events'], 'action');
ok(in_array('journal_entry.draft', $acts, true) && in_array('journal_entry.post', $acts, true) && array_search('journal_entry.draft', $acts) < array_search('journal_entry.post', $acts), 'a journal entry: drafted, then posted — oldest first (' . implode(', ', array_unique($acts)) . ')');
$post = array_values(array_filter($h['events'], fn ($e) => $e['action'] === 'journal_entry.post'))[0];
ok($post['sentence'] === "SMOKE Carl posted an entry ($capNum, 5000.00 USD)" && $post['after']['amount'] === '5000.00' && $post['actor_kind'] === 'human', 'the post in words with its number and amount: "' . $post['sentence'] . '"');
$n = $AD($BEA, 'record_history', ['record_type' => 'journal_entry', 'number' => $capNum, 'order' => 'newest']);
ok($n['record_id'] === $W['capital'] && $n['events'][0]['activity_id'] > end($n['events'])['activity_id'], 'by number, newest first');
$inv = $AD($BEA, 'record_history', ['record_type' => 'invoice', 'number' => (string) one('SELECT number FROM invoices WHERE id = :i', ['i' => $W['inv_a1']])]);
$iss = array_values(array_filter($inv['events'], fn ($e) => $e['action'] === 'invoice.issue'))[0] ?? [];
ok(str_contains($iss['sentence'] ?? '', 'issued an invoice') && str_contains($iss['sentence'], '1082.50 USD'), 'an invoice: issued, with its amount ("' . ($iss['sentence'] ?? '-') . '")');
$cu = $AD($BEA, 'record_history', ['record_type' => 'customer', 'record_id' => $W['acme']]);
ok(count(array_filter($cu['events'], fn ($e) => str_starts_with($e['action'], 'invoice.'))) >= 2 && count(array_filter($cu['events'], fn ($e) => str_starts_with($e['action'], 'receipt.'))) >= 1, 'a customer\'s history carries its invoices\' and receipts\' events (they carry the customer\'s key)');
ok($A($BEA, 'record_history', ['record_type' => 'invoice', 'number' => 'INV-99999'])['error'] && $A($BEA, 'record_history', ['record_type' => 'bill'])['error'], 'an unknown number, or none named, is a refusal in words');
ok(count($AD($BEA, 'record_history', ['record_type' => 'bill', 'record_id' => 99999])['events']) === 0, 'a record with no events has an empty history');
echo "2. actor_timeline and who_touched\n";
$t = $AD($CARL, 'actor_timeline', []);
ok($t['count'] >= 5 && count(array_unique(array_column($t['events'], 'actor_member_id'))) === 1 && $t['events'][0]['actor_member_id'] === 28, 'Carl\'s own timeline by default (' . $t['count'] . ' events), newest first');
$t = $AD($CARL, 'actor_timeline', ['action' => 'journal_entry.post']);
ok($t['count'] >= 4 && array_unique(array_column($t['events'], 'action')) === ['journal_entry.post'], 'an action filter');
$t = $AD($CARL, 'actor_timeline', ['action' => 'journal_entry.', 'limit' => 2]);
ok($t['count'] === 2, 'a prefix filter and a limit');
$vt = $AD($VERA, 'actor_timeline', ['member_id' => 28, 'action' => 'journal_entry.post']);
ok($vt['count'] >= 4 && $vt['note'] === null, 'the books are business-wide: anyone with reports.view reads another person\'s timeline');
act_token('/notes/save.php', ['record_type' => 'bill', 'record_id' => $W['bill_h1'], 'body' => 'SMOKE agent note: ' . str_repeat('x', 220) . 'SECRET-BODY-TEXT'], ['X-Action-Token: ' . person_token(40)]);
$ag = $AD($BEA, 'actor_timeline', ['actor_kind' => 'agent']);
ok($ag['count'] >= 1 && array_unique(array_column($ag['events'], 'actor_kind')) === ['agent'] && $ag['events'][0]['actor_name'] === 'SMOKE Bookkeeper', 'actor_kind=agent: what the agents did');
ok(!str_contains(json_encode($ag), 'SECRET-BODY-TEXT') && isset($ag['events'][0]['after']['excerpt']), 'a long note is logged by its 200-character excerpt, never its full text');
ok($A($BEA, 'actor_timeline', ['from' => 'last week'])['error'], 'a bad date is a refusal in words');
$w = $AD($BEA, 'who_touched', ['record_type' => 'journal_entry', 'record_id' => $W['capital']]);
ok(count($w['people']) === 1 && $w['people'][0]['actor_name'] === 'SMOKE Carl' && $w['people'][0]['events'] >= 2 && $w['people'][0]['last_action'] === 'journal_entry.post' && $w['people'][0]['last_action_words'] === 'posted an entry', 'who_touched: Carl, how many times, the last thing he did in words');
$wb = $AD($BEA, 'who_touched', ['record_type' => 'bill', 'record_id' => $W['bill_h1']]);
ok(count($wb['people']) >= 2 && in_array('SMOKE Bookkeeper', array_column($wb['people'], 'actor_name'), true), 'a bill was touched by several (Bea, Carl and the agent\'s note)');
echo "3. period_activity\n";
$febId = period_id('2026-02');
$pa = $AD($CARL, 'period_activity', ['period_id' => $febId]);
ok(count($pa['closes']) === 1 && count($pa['reopens']) === 1 && $pa['reopens'][0]['after']['reason'] === 'SMOKE: a late vendor bill' && $pa['reopens'][0]['actor_name'] === 'SMOKE Carl', 'February: closed once, reopened once with the reason and who');
ok(count($pa['posted_after_reopen']) === 1 && $pa['posted_after_reopen'][0]['entity_id'] === $W['late'] && $pa['posted_after_reopen'][0]['after']['reopened_period'] === true, 'and exactly the late entry posted into it after the reopening (not the one before)');
$byName = $AD($CARL, 'period_activity', ['name' => '2026-02']);
ok($byName['period_id'] === $febId && $A($CARL, 'period_activity', ['name' => '2031-01'])['error'], 'by name too; an unknown period is a refusal');
$mar = $AD($CARL, 'period_activity', ['period_id' => period_id('2026-03')]);
ok(count($mar['reversals']) === 1 && $mar['reversals'][0]['after']['reason'] === 'SMOKE: wrong account' && count($mar['reopens']) === 0, 'March: the reversal with its reason, no reopening');
echo "4. config_change_log, changes_since, search\n";
act(as_member(1), '/settings/tax-rates/save.php', ['name' => 'SMOKE Cfg 5%', 'rate' => '5']);
$cl = $AD($CARL, 'config_change_log', []);
$tx = array_values(array_filter($cl['changes'], fn ($c) => $c['action'] === 'tax_rate.save'))[0] ?? [];
ok(str_contains($tx['sentence'] ?? '', 'changed a tax rate') && $tx['actor_name'] === 'SMOKE Owner', 'config_change_log: the tax rate change, who and in words');
ok(count(array_filter($cl['changes'], fn ($c) => str_starts_with($c['action'], 'invoice.') || str_starts_with($c['action'], 'journal_entry.'))) === 0 && count($AD($CARL, 'config_change_log', ['entity_type' => 'nonsense'])['changes']) === 0, 'only configuration: no documents, no entries; an entity filter');
$cs = $AD($CARL, 'changes_since', ['since' => date('Y-m-d')]);
$byAction = array_column($cs['by_action'], 'events', 'action');
ok(($byAction['journal_entry.post'] ?? 0) >= 4 && isset($byAction['invoice.issue']) && !isset($byAction['screen.view']) && count($cs['records_touched']) >= 5, 'changes_since today: counts by action (posts, issues…), screen views not counted, the records touched');
$cb = $AD($CARL, 'changes_since', ['since' => date('Y-m-d'), 'kinds' => ['bill.']]);
ok(count($cb['by_action']) >= 1 && count(array_filter($cb['by_action'], fn ($a) => !str_starts_with($a['action'], 'bill.'))) === 0 && $cb['by_action'][0]['words'] !== null, 'kinds=[bill.]: only bill actions, with their words');
ok(count($AD($CARL, 'changes_since', ['since' => '2031-01-01'])['by_action']) === 0 && $A($CARL, 'changes_since', ['since' => 'yesterday-ish'])['error'], 'a future time: nothing; a bad time: refused');
$s = $AD($BEA, 'activity_search', ['sql' => "SELECT action, count(*) AS n FROM mcp_activity_log WHERE action = 'journal_entry.post' GROUP BY 1"]);
ok($s[0]['action'] === 'journal_entry.post' && $s[0]['n'] >= 4, 'activity_search: a SELECT over the log answers');
foreach (['DELETE FROM activity_log' => 'Only a single SELECT', "SELECT set_config('app.member_id', '1', true)" => 'not available', 'SELECT * FROM activity_log' => null] as $sql => $why) {
    $c = $A($BEA, 'activity_search', ['sql' => $sql]);
    ok($c['error'] && ($why === null || str_contains($c['text'], $why)), 'refused: ' . $sql);
}
$leak = $AD($BEA, 'activity_search', ['sql' => "SELECT count(*) AS n FROM mcp_activity_log WHERE before::text ~* 'token|password|secret' OR after::text ~* 'token_hash|password|SECRET-BODY|@example.invalid'"]);
ok($leak[0]['n'] === 0, 'no payload in the log carries a token, a password, a note\'s full text or an address');
ok(count(array_filter(array_keys((array) $AD($BEA, 'record_history', ['record_type' => 'invoice', 'record_id' => $W['inv_a1']])['events'][0]), fn ($k) => in_array($k, ['ip_address', 'session_id', 'request_id']))) === 0, 'an event row carries no address, session or request id');
finish();
